#include <stdio.h>
#include <string.h>

int main() {
    for (int i = 1; i <= 100; i++) {
        printf("%d", i);

        char output[64] = {0};
        if (i % 3 == 0) {
            strcat(output, "fizz");
        }
        if (i % 5 == 0) {
            strcat(output, "buzz");
        }

        printf(" %s\n", !strlen(output) ? "" : output);
    }
    return 0;
}

